using UnityEngine;
using System.Collections.Generic;
[DefaultExecutionOrder(300)]
public sealed class NiaolongFeedback:MonoBehaviour
{
 NiaolongCompanion c;readonly List<GameObject> icons=new List<GameObject>();readonly List<Material> materials=new List<Material>();readonly List<Mesh> meshes=new List<Mesh>();
 void Awake(){c=GetComponent<NiaolongCompanion>();for(int i=0;i<11;i++){var go=new GameObject(i<3?"Sleep Z":i<7?"Wish star":i<9?"Happy heart":i==9?"Surprise !":"Concern drop");go.transform.SetParent(transform,false);var m=new Mesh();var v=new List<Vector3>();var tr=new List<int>();
 void Poly(List<Vector2> p){int k=v.Count;Vector2 center=Vector2.zero;foreach(var q in p)center+=q;center/=p.Count;v.Add(center);foreach(var q in p)v.Add(q);for(int a=0;a<p.Count;a++){int b=k+1+a,d=k+1+(a+1)%p.Count;tr.Add(k);tr.Add(b);tr.Add(d);tr.Add(k);tr.Add(d);tr.Add(b);}}
 void Stroke(Vector2 a,Vector2 b,float width){Vector2 n=new Vector2(-(b-a).y,(b-a).x).normalized*width*.5f;Poly(new List<Vector2>{a+n,a-n,b-n,b+n});}
 if(i<3){Stroke(new Vector2(-.4f,.5f),new Vector2(.4f,.5f),.16f);Stroke(new Vector2(.4f,.5f),new Vector2(-.4f,-.5f),.16f);Stroke(new Vector2(-.4f,-.5f),new Vector2(.4f,-.5f),.16f);}else if(i<7){var p=new List<Vector2>();for(int k=0;k<10;k++){float a=k*Mathf.PI/5+Mathf.PI*.5f;float radius=k%2==0?.55f:.23f;p.Add(new Vector2(Mathf.Cos(a),Mathf.Sin(a))*radius);}Poly(p);}else if(i<9){var p=new List<Vector2>();for(int k=0;k<40;k++){float a=k/40f*Mathf.PI*2;float x=16*Mathf.Pow(Mathf.Sin(a),3),y=13*Mathf.Cos(a)-5*Mathf.Cos(2*a)-2*Mathf.Cos(3*a)-Mathf.Cos(4*a);p.Add(new Vector2(x,y)/30);}Poly(p);}else if(i==9){Stroke(new Vector2(0,.55f),new Vector2(0,-.14f),.18f);Poly(new List<Vector2>{new Vector2(-.1f,-.35f),new Vector2(.1f,-.35f),new Vector2(.1f,-.55f),new Vector2(-.1f,-.55f)});}else{var p=new List<Vector2>();p.Add(new Vector2(0,.65f));for(int k=0;k<=24;k++){float a=k/24f*Mathf.PI*1.6f-Mathf.PI*.3f;p.Add(new Vector2(.32f*Mathf.Cos(a),-.12f+.32f*Mathf.Sin(a)));}Poly(p);}
 m.SetVertices(v);m.SetTriangles(tr,0);m.RecalculateNormals();m.RecalculateBounds();meshes.Add(m);go.AddComponent<MeshFilter>().sharedMesh=m;var r=go.AddComponent<MeshRenderer>();r.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;var mat=new Material(Shader.Find("Universal Render Pipeline/Unlit"));mat.color=i<3?new Color(.54f,.74f,1):i<7?new Color(1,.77f,.2f):i<9?new Color(1,.43f,.53f):i==9?new Color(1,.57f,.16f):new Color(.37f,.78f,1);r.sharedMaterial=mat;materials.Add(mat);icons.Add(go);go.SetActive(false);}}
 void LateUpdate(){if(!c)return;float t=c.ActionTime,e=c.Blend;for(int i=0;i<icons.Count;i++){bool show=c.Equipped&&c.Visibility>.9f&&e>.03f&&((i<3&&c.Action==NiaolongCompanion.Gesture.SleepyNod)||(i>=3&&i<7&&c.Action==NiaolongCompanion.Gesture.StarWish)||(i>=7&&i<9&&c.Action==NiaolongCompanion.Gesture.HappyBounce)||(i==9&&c.Action==NiaolongCompanion.Gesture.Surprised)||(i==10&&c.Action==NiaolongCompanion.Gesture.Comfort));var go=icons[i];go.SetActive(show);if(!show)continue;float size=.13f;Vector3 p;if(i<3){float q=Mathf.Repeat(t*.35f+i*.31f,1);p=new Vector3(.28f+q*.17f,.85f+q*.35f,.05f);size=.08f+.06f*q;}else if(i<7){float a=t*1.8f+(i-3)*Mathf.PI*.5f;p=new Vector3(.32f*Mathf.Cos(a),.60f+.15f*Mathf.Sin(a*1.3f),.25f+.22f*Mathf.Sin(a));size=.085f;}else if(i<9){p=new Vector3((i==7?-.23f:.23f),1.05f+.07f*Mathf.Sin(t*3+i),.05f);size=.14f;}else p=new Vector3(.25f,1.08f,0);go.transform.localPosition=p;go.transform.localScale=Vector3.one*size*e*(1+.08f*Mathf.Sin(t*4));if(Camera.main)go.transform.rotation=Camera.main.transform.rotation;}}
 void OnDestroy(){foreach(var m in materials)Destroy(m);foreach(var m in meshes)Destroy(m);}
}
